using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.Reflection;using System.Windows.Forms;using System.Drawing;using System.ComponentModel;using System.Security.Principal;using System.Web.Script.Serialization;using Microsoft.Win32;
namespace EnhancedZune {
 public class Preference {public string key,name,kind;public object before,after;public bool existed;}
 public class UserPreferences {
  public string target;public List<Preference> values=new List<Preference>();
  static JavaScriptSerializer json=new JavaScriptSerializer();
  internal static string TestRoot=null; public static string Root {get{if(TestRoot!=null)return TestRoot;return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"EnhancedZune","SettingsBackups");}}
  public static void Apply(string target,bool defaults,bool dpi){UserPreferences b=new UserPreferences{target=Engine.Full(target)};
   Action<string,string,object,RegistryValueKind> set=delegate(string key,string name,object value,RegistryValueKind kind){using(RegistryKey k=Registry.CurrentUser.CreateSubKey(key)){bool exists=k.GetValueNames().Contains(name);Preference p=new Preference{key=key,name=name,kind=exists?k.GetValueKind(name).ToString():kind.ToString(),existed=exists,before=exists?k.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames):null,after=value};if(exists&&k.GetValueKind(name)!=kind)throw new IOException("Unexpected preference type: "+name);if(!exists||!Object.Equals(k.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames),value))b.values.Add(p);}};
   string shellDefaults=@"Software\Microsoft\Zune\Shell";
   using(RegistryKey existing=Registry.CurrentUser.OpenSubKey(shellDefaults)){
    foreach(string name in new[]{"BackgroundInterfaceTheme","InterfaceScalingChoice","AlbumArtworkQuality"})if(!defaults&&(existing==null||existing.GetValue(name)==null))set(shellDefaults,name,0,RegistryValueKind.DWord);
   }
   if(defaults){string shell=@"Software\Microsoft\Zune\Shell",general=@"Software\Microsoft\Zune\GeneralSettings";set(shell,"BackgroundImage","res://ZuneShellResources!FrameBackground06.png",RegistryValueKind.String);set(shell,"BackgroundColor",-1052689,RegistryValueKind.DWord);set(shell,"BackgroundInterfaceTheme",0,RegistryValueKind.DWord);set(shell,"InterfaceScalingChoice",0,RegistryValueKind.DWord);set(shell,"AlbumArtworkQuality",0,RegistryValueKind.DWord);set(general,"RenderingType",1,RegistryValueKind.DWord);set(general,"RenderingQuality",1,RegistryValueKind.DWord);set(general,"AnimationsEnabled",1,RegistryValueKind.DWord);set(general,"ReevaluateVideoSettings",0,RegistryValueKind.DWord);}
   if(dpi){string key=@"Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers",name=Path.Combine(target,"Zune.exe");using(RegistryKey k=Registry.CurrentUser.OpenSubKey(key)){string old=k==null?"":Convert.ToString(k.GetValue(name,""));string[] flags=old.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries).Where(x=>x!="~"&&x!="GDIDPISCALING"&&x!="DPIUNAWARE"&&x!="HIGHDPIAWARE").ToArray();set(key,name,"~ "+String.Join(" ",flags.Concat(new[]{"HIGHDPIAWARE"})),RegistryValueKind.String);}}
   if(b.values.Count==0)return;Directory.CreateDirectory(Root);string file=Path.Combine(Root,DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff")+".json");File.WriteAllText(file,json.Serialize(b));try{foreach(Preference p in b.values)Write(p,true);}catch{foreach(Preference p in b.values)Write(p,false);throw;}
  }
  static object Value(Preference p,bool after){object v=after?p.after:p.before;if(p.kind=="DWord")return unchecked((int)Convert.ToInt64(v));return v;}
  static void Write(Preference p,bool after){using(RegistryKey k=Registry.CurrentUser.CreateSubKey(p.key)){if(!after&&!p.existed)k.DeleteValue(p.name,false);else k.SetValue(p.name,Value(p,after),(RegistryValueKind)Enum.Parse(typeof(RegistryValueKind),p.kind));}}
  public static void Restore(string target){if(!Directory.Exists(Root))return;foreach(string file in Directory.GetFiles(Root,"*.json").OrderByDescending(x=>x)){UserPreferences b=json.Deserialize<UserPreferences>(File.ReadAllText(file));if(!Engine.Full(b.target).Equals(Engine.Full(target),StringComparison.OrdinalIgnoreCase))continue;foreach(Preference p in b.values){using(RegistryKey k=Registry.CurrentUser.OpenSubKey(p.key)){object now=k==null?null:k.GetValue(p.name);if(now!=null&&String.Equals(Convert.ToString(now),Convert.ToString(Value(p,true)),StringComparison.Ordinal))Write(p,false);}}File.Move(file,file+".restored");}}
 }
 public sealed class SetupForm:Form {
  readonly TextBox path=new TextBox(),log=new TextBox();readonly FlowLayoutPanel actions=new FlowLayoutPanel(),completion=new FlowLayoutPanel();
  readonly CheckBox dpi=new CheckBox(),defaults=new CheckBox(),launch=new CheckBox();readonly Button browseButton=new Button(),finish=new Button();
  readonly Label status=new Label(),detail=new Label();readonly TableLayoutPanel banner=new TableLayoutPanel();
  readonly string[] worker;bool busy=false,completed=false,launchAllowed=false;string completedTarget="";public int Code=1;internal bool PreviewMode=false;
  public SetupForm(string[] args){worker=args.Length>0?args:null;Text="Enhanced Zune Setup · 1.0.0 RC7";Font=new Font("Segoe UI",11);MinimumSize=new Size(800,800);Size=new Size(900,880);StartPosition=FormStartPosition.CenterScreen;AutoScaleMode=AutoScaleMode.Dpi;BackColor=Color.FromArgb(248,248,248);
   TableLayoutPanel layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=10};Controls.Add(layout);
   foreach(int height in new[]{50,54,44,34,44,40,142})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,height));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));
   layout.Controls.Add(new Label{Text="Enhanced Zune",Font=new Font("Segoe UI",24),ForeColor=Color.FromArgb(205,0,120),AutoSize=true});
   layout.Controls.Add(new Label{Text="For original x64 Zune 4.8.2345 on Windows 10 / 11.\r\nLocal test candidate — public release checks remain incomplete.",Dock=DockStyle.Fill});
   TableLayoutPanel browse=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};browse.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));browse.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,120));path.Text=Detect();path.Dock=DockStyle.Fill;browseButton.Text="Browse…";browseButton.Dock=DockStyle.Fill;browseButton.Click+=delegate{using(FolderBrowserDialog d=new FolderBrowserDialog()){d.Description="Choose the folder containing Zune.exe";if(d.ShowDialog()==DialogResult.OK)path.Text=d.SelectedPath;}};browse.Controls.Add(path);browse.Controls.Add(browseButton);layout.Controls.Add(browse);
   dpi.Text="Enable crisp rendering for this Windows account (recommended)";dpi.Checked=true;dpi.Dock=DockStyle.Fill;layout.Controls.Add(dpi);defaults.Text="Reset display settings: white theme, automatic scale, Basic artwork";defaults.Checked=false;defaults.Dock=DockStyle.Fill;layout.Controls.Add(defaults);
   layout.Controls.Add(new Label{Text="Your music, library and personal files stay in place. Close Zune before installing.",Dock=DockStyle.Fill});actions.Dock=DockStyle.Fill;actions.WrapContents=true;layout.Controls.Add(actions);
   Add("Install / verify",delegate{Run("install");});Add("Repair",delegate{Run("repair");});Add("Restore originals",delegate{Run("restore");});Add("Download Zune",DownloadZune);Add("Install downloaded Zune…",Media);Add("Prerequisites…",ShowPrerequisites);Add("Open backups",delegate{if(Directory.Exists(Engine.StateRoot))Process.Start(Engine.StateRoot);else MessageBox.Show(this,"No enhancement backups exist yet.");});
   banner.Dock=DockStyle.Fill;banner.AutoSize=true;banner.Padding=new Padding(14,10,14,10);banner.Margin=new Padding(0,4,0,12);banner.ColumnCount=1;banner.RowCount=2;status.Font=new Font("Segoe UI",16,FontStyle.Bold);status.AutoSize=true;detail.AutoSize=true;detail.Margin=new Padding(0,6,0,0);banner.Controls.Add(status);banner.Controls.Add(detail);layout.Controls.Add(banner);
   completion.Dock=DockStyle.Fill;completion.AutoSize=true;completion.WrapContents=true;completion.Padding=new Padding(0,0,0,12);launch.Text="Launch Zune when setup closes";launch.Checked=true;launch.CheckedChanged+=delegate{if(completed&&launchAllowed)detail.Text=launch.Checked?"Click Finish to close setup and open Zune. Uncheck the option below to open it later.":"Click Finish to close setup. You can open Zune later from Start.";};launch.AutoSize=true;launch.Margin=new Padding(0,8,18,0);completion.Controls.Add(launch);finish.Text="Finish";finish.Font=new Font("Segoe UI",12,FontStyle.Bold);finish.AutoSize=true;finish.Padding=new Padding(20,5,20,5);finish.BackColor=Color.FromArgb(205,0,120);finish.ForeColor=Color.White;finish.FlatStyle=FlatStyle.Flat;finish.Click+=delegate{Close();};completion.Controls.Add(finish);completion.Visible=false;layout.Controls.Add(completion);
   log.Dock=DockStyle.Fill;log.Multiline=true;log.AutoSize=false;log.MinimumSize=new Size(0,150);log.ReadOnly=true;log.ScrollBars=ScrollBars.Vertical;log.BackColor=Color.White;layout.Controls.Add(log,0,9);
   Resize+=delegate{status.MaximumSize=new Size(Math.Max(300,ClientSize.Width-100),0);detail.MaximumSize=status.MaximumSize;};status.MaximumSize=new Size(760,0);detail.MaximumSize=status.MaximumSize;
   Stage("Close Zune, then choose Install / verify","Choose Prerequisites if Windows components are missing.","attention");
   FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;MessageBox.Show(this,"Please wait for the current operation to finish. Recovery records are being maintained.");}};
   FormClosed+=delegate{if(!PreviewMode&&completed&&launchAllowed&&launch.Checked){try{Process.Start(new ProcessStartInfo(Path.Combine(completedTarget,"Zune.exe")){UseShellExecute=true,WorkingDirectory=completedTarget});}catch(Exception e){MessageBox.Show("Installation is complete, but Zune could not be opened. You can open it from Start.\r\n\r\n"+e.Message,"Open Zune");}}};
   Shown+=delegate{string[] overrides=RuntimeTrust.Overrides();if(overrides.Length>0){Log("Runtime compatibility note: this PC has existing .NET strong-name verification overrides. Successful loading here does not certify a clean runtime. Setup does not change these overrides.");foreach(string item in overrides)Log(item);}};
   if(worker!=null){path.Text=worker.Length>1?worker[1]:path.Text;Busy(true);Shown+=delegate{BeginWorker();};}
  }
  void Add(string text,Action action){Button b=new Button{Text=text,AutoSize=true,Height=36,Margin=new Padding(0,0,10,8)};b.Click+=delegate{try{action();}catch(Exception e){Stage("Setup needs attention",e.Message,"error");Log(e.Message);}};actions.Controls.Add(b);}
  internal void Stage(string heading,string instruction,string kind){status.Text=heading;detail.Text=instruction;status.ForeColor=kind=="success"?Color.FromArgb(20,105,45):kind=="error"?Color.FromArgb(170,25,25):kind=="working"?Color.FromArgb(0,85,145):Color.FromArgb(130,70,0);banner.BackColor=kind=="success"?Color.FromArgb(229,245,233):kind=="error"?Color.FromArgb(255,232,232):kind=="working"?Color.FromArgb(230,241,250):Color.FromArgb(255,243,218);}
  void Busy(bool value){busy=value;actions.Enabled=!value;path.Enabled=!value;browseButton.Enabled=!value;dpi.Enabled=!value;defaults.Enabled=!value;if(value){completed=false;launchAllowed=false;completion.Visible=false;}}
  public void Log(string s){if(InvokeRequired){BeginInvoke(new Action<string>(Log),s);return;}log.AppendText(s+Environment.NewLine);}
  public static string Detect(){foreach(RegistryView view in new[]{RegistryView.Registry64,RegistryView.Registry32})using(RegistryKey lm=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,view))using(RegistryKey k=lm.OpenSubKey(@"SOFTWARE\Microsoft\Zune")){if(k!=null){string p=Convert.ToString(k.GetValue("Installation Directory",k.GetValue("InstallPath","")));if(File.Exists(Path.Combine(p,"Zune.exe")))return p;}}return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"Zune");}
  internal void ShowCompletion(string op,string target,bool restart,bool elevated){completed=true;completedTarget=target;launchAllowed=CompletionPolicy.MayLaunch(true,op,restart,elevated);launch.Visible=launchAllowed;launch.Checked=true;completion.Visible=true;AcceptButton=finish;
   if(restart)Stage("Restart Windows to continue","Save your work and restart Windows before opening Zune. Setup will not restart automatically.","attention");
   else if(op=="restore")Stage("Original files restored","Choose Install / verify to apply the current enhancements, or Finish to close setup.","success");
   else Stage(op=="repair"?"Repair complete":"Installation complete",launchAllowed?"Click Finish to close setup and open Zune. Uncheck the option below to open it later.":"Click Finish to close setup. Open Zune normally from Start; this setup is running as administrator.","success");
  }
  void Run(string op){completed=false;launchAllowed=false;completion.Visible=false;string target=Engine.Full(path.Text);if(!File.Exists(Path.Combine(target,"Zune.exe")))throw new IOException("Zune was not found here. Choose Download Zune, then Install downloaded Zune, or browse to your existing installation.");if(Process.GetProcessesByName("Zune").Length>0)throw new IOException("Close Zune and try again. Setup will not forcibly close it.");if(op=="restore"&&MessageBox.Show(this,"Restore the verified original program files? Your music library stays in place. Later unknown file modifications will be protected.","Restore originals",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;
   if(op!="restore"&&!EnhancedZune.Prerequisites.Ensure(this)){Stage("Windows components need attention","Open Prerequisites to install missing components or follow Microsoft's instructions.","attention");return;}
   string exe=Assembly.GetExecutingAssembly().Location;ProcessStartInfo psi=new ProcessStartInfo(exe,"--"+op+" \""+target+"\""){UseShellExecute=true,Verb="runas"};Busy(true);Stage("Installing — please wait","Approve the Windows administrator prompt, then keep setup open until it finishes.","working");BackgroundWorker w=new BackgroundWorker();int exit=-1;
   w.DoWork+=delegate{using(Process p=Process.Start(psi)){p.WaitForExit();exit=p.ExitCode;}};
   w.RunWorkerCompleted+=delegate(object sender,RunWorkerCompletedEventArgs e){Busy(false);if(e.Error!=null){Stage("Setup did not start","No success was reported. Review the details below and retry.","error");Log(e.Error.Message);return;}if(exit!=0){Stage("Setup did not complete","Review the details in the setup window and backup journal before retrying.","error");Log("Operation returned "+exit+". No success is assumed.");return;}
    try{if(op=="restore"){UserPreferences.Restore(target);using(RegistryKey shell=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Zune\Shell",true)){if(shell!=null&&Convert.ToString(shell.GetValue("BackgroundImage","")).StartsWith("res://ZuneShellResources!FrameBackgroundCustom",StringComparison.OrdinalIgnoreCase))shell.SetValue("BackgroundImage","res://ZuneShellResources!FrameBackground06.png",RegistryValueKind.String);}}else if(op=="install")UserPreferences.Apply(target,defaults.Checked,dpi.Checked);
     bool restart=EnhancedZune.Prerequisites.RestartRequiredBySetup||EnhancedZune.Prerequisites.Detect().RestartPending;ShowCompletion(op,target,restart,WindowsComponents.Elevated);Log("Completed. Program backups: "+Engine.StateRoot+"\r\nAccount settings backups: "+UserPreferences.Root);
    }catch(Exception error){Stage("Program files completed; settings need attention","Review the details below. Zune will not open automatically.","attention");Log(error.Message);}
   };w.RunWorkerAsync();
  }
  void BeginWorker(){Stage("Working — keep setup open","The installer is verifying files and maintaining recovery records.","working");BackgroundWorker w=new BackgroundWorker();string target=Engine.Full(path.Text);
   w.DoWork+=delegate{using(Bundle b=new Bundle())using(System.Threading.Mutex mutex=new System.Threading.Mutex(false,@"Global\EnhancedZune.Setup")){if(!mutex.WaitOne(0))throw new IOException("Another Enhanced Zune setup is running.");try{if(worker[0]!="--restore"&&!EnhancedZune.Prerequisites.Detect().Ready)throw new IOException("Required Windows components are missing. Open Prerequisites and recheck.");if(worker[0]=="--install")Engine.Install(target,b,Log);else if(worker[0]=="--restore"){string backup=Engine.Latest(target);if(backup==null)throw new IOException("No recoverable enhancement backup was found.");Engine.RestoreKnown(target,backup,b,Log);}else if(worker[0]=="--repair")Engine.Repair(target,b,Log);else throw new IOException("Unknown setup operation.");}finally{mutex.ReleaseMutex();}}};
   w.RunWorkerCompleted+=delegate(object sender,RunWorkerCompletedEventArgs e){Busy(false);Code=e.Error==null?0:1;if(e.Error==null){Close();return;}Stage("Operation stopped","Read the error below, then close this window to return to setup.","error");Log(e.Error.Message);actions.Controls.Clear();Add("Return to setup",Close);};w.RunWorkerAsync();
  }
  void ShowPrerequisites(){using(PrerequisiteForm f=new PrerequisiteForm())f.ShowDialog(this);}
  void DownloadZune(){Process.Start(new ProcessStartInfo(MediaPackage.DownloadUrl){UseShellExecute=true});Stage("Download Zune","The download opens in your browser. When it finishes, choose Install downloaded Zune and select the ZIP. No extraction needed.","attention");Log("Original Zune download source: Zune Update, a community archive. "+MediaPackage.DownloadUrl);}
  void MediaProgress(string message){if(InvokeRequired){BeginInvoke(new Action<string>(MediaProgress),message);return;}Stage(message.StartsWith("Installing")?"Installing original Zune":"Preparing Zune",message,"working");}
  void Media(){MediaInstall.Run(this,Busy,delegate(string message){Log(message);if(message.Contains("requires a Windows restart")){EnhancedZune.Prerequisites.RestartRequiredBySetup=true;ShowCompletion("install",Detect(),true,WindowsComponents.Elevated);detail.Text="Microsoft setup requires a restart. Restart Windows, then run this setup again to apply enhancements.";return;}Stage("Original setup needs attention",message,"attention");},delegate{path.Text=Detect();try{Run("install");}catch(Exception e){Stage("Setup needs attention",e.Message,"error");Log(e.Message);}},MediaProgress);}

 }
 public static class Program {
  [STAThread]public static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{
   if(!Engine.NativeX64()||Environment.OSVersion.Version.Major<10)throw new IOException("This release requires x64 Windows 10 or Windows 11. ARM64 and x86 are not supported.");
   if(args.Length==1&&args[0]=="--windows-components"){using(WindowsComponentForm f=new WindowsComponentForm()){Application.Run(f);return f.Code;}}
   if(args.Length==1&&args[0]=="--check-ui"){using(SetupForm check=new SetupForm(new string[0]))using(Timer timer=new Timer()){check.PreviewMode=true;timer.Interval=1500;timer.Tick+=delegate{timer.Stop();check.Close();};check.Shown+=delegate{timer.Start();};Application.Run(check);return 0;}}
   if(args.Length>0&&(args.Length!=2||!(new[]{"--install","--restore","--repair"}).Contains(args[0])))throw new IOException("Open setup normally to install or recover Enhanced Zune.");using(SetupForm f=new SetupForm(args)){Application.Run(f);return args.Length==0?0:f.Code;}
  }catch(Exception e){MessageBox.Show(e.Message,"Enhanced Zune Setup",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 }
}

